static size_t heapLive=0,heapPeak=0;static std::map<void*,size_t> allocations;static int failAllocation=-1;
size_t heap_caps_get_free_size(unsigned){return 32u*1024u*1024u-heapLive;}
void*heap_caps_malloc(size_t n,unsigned){if(failAllocation==0)return nullptr;if(failAllocation>0)--failAllocation;void*p=std::malloc(n);if(p){allocations[p]=n;heapLive+=n;heapPeak=std::max(heapPeak,heapLive);}return p;}
void heap_caps_free(void*p){if(!p)return;check(allocations.count(p)==1,"free owns one live PSRAM allocation");heapLive-=allocations[p];allocations.erase(p);std::free(p);}
static size_t lvglLive=0,lvglPeak=0;static std::map<void*,size_t> lvglAllocations;
void* lvgl_host_malloc(size_t n,unsigned){void* p=std::malloc(n);if(p){lvglAllocations[p]=n;lvglLive+=n;lvglPeak=std::max(lvglPeak,lvglLive);}return p;}
void lvgl_host_free(void* p){if(!p)return;check(lvglAllocations.count(p)==1,"LVGL frees owned backing");lvglLive-=lvglAllocations[p];lvglAllocations.erase(p);std::free(p);}
