static void logicalMouse(lv_point_t p,uint8_t buttons,int wheel=0){
 // Production Tab5Mouse feeds the primary LVGL event before its logical callback.
 point=p;pressed=buttons&1;testMillis+=20;lv_tick_inc(20);lv_indev_read(touch);
 Tab5ImageEditor::mouse(p.x,p.y,buttons,wheel);lv_timer_handler();lv_obj_update_layout(screen);
}
